jsEchartScriptFunc = function (queryData, option, echarts, context) {
  /* ==========================================================================
     KHUNG TAB BAN CHỈ ĐẠO 57 (Luật 1 + Luật 4)
     Header + 3 tab: Nhiệm vụ 57 (gộp TP + Xã/phường) / Chuyên đề lớn (kèm số) / Tình hình triển khai thí điểm,
     nút Nhiệm vụ giao/nhận (kèm số), Xuất tổng hợp Excel, Toàn màn hình.
     URL có ?id_xa_phuong= → chỉ còn tab Nhiệm vụ 57, truyền tham số để bộ lọc khoá vào xã/phường đó.
     Mỗi tab nhúng 1 dashboard Superset bằng iframe (lazy load, giữ trạng thái khi đổi tab).
     ========================================================================== */
  const elementId = context && context.elementId ? context.elementId : "bcd57-khung-tab";
  const width = context && context.width ? context.width : null;
  const height = context && context.height ? context.height : null;
  const rootEl = document.getElementById(elementId);
  if (!rootEl) return option;

  // dọn timer/listener của lần render trước
  if (rootEl.__bcdTabCleanup) {
    try {
      rootEl.__bcdTabCleanup();
    } catch (e) {}
  }

  // ============ 1. CẤU HÌNH ============
  const CONFIG = {
    title: "BAN CHỈ ĐẠO 57",
    subText: "Theo dõi, đôn đốc thực hiện nhiệm vụ phát triển KHCN, ĐMST & chuyển đổi số",
    logoSrc:
      "data:image/png;base64,",
    passParams: ["iddv", "iddvcha", "id_xa_phuong"], // tham số URL truyền tiếp xuống dashboard con
    defaultTab: "nv",
    showExport: true, // nút "Xuất tổng hợp Excel" (gửi lệnh cho dashboard con đang mở)
    exportMessage: "bcd57-export-excel",
    // Nút Nhiệm vụ giao / Nhiệm vụ nhận (theo v39) – chỉ hiện ở tab có showView.
    // Bấm → gửi {type: viewMessage, view} cho dashboard con; dashboard con gửi lại
    // {type: countMessage, nv, giao, nhan, cd} để cập nhật số trên tab và nút.
    viewMessage: "bcd57-view",
    countMessage: "bcd57-counts",
    defaultView: "nhan",
    // Số ban đầu khi dashboard con chưa gửi số thật (cd: 10 chuyên đề cố định)
    initCounts: { nv: 0, giao: 0, nhan: 0, cd: 10 },
  };

  // url để trống = chưa có dashboard → hiện ô "Chưa cấu hình"
  const TAB_CONFIG = [
    {
      id: "nv",
      no: 1,
      label: "Nhiệm vụ 57", // gộp cấp Thành phố + Xã/phường, phân cấp qua bộ lọc "Góc view"
      url: "https://superbi-theodoinhiemvu.hanoi.gov.vn/superset/dashboard/bcd57-nv-cap-tp/",
      // ?id_xa_phuong= vẫn mở dashboard này (dữ liệu gộp TP + xã); bộ lọc tự khoá vào xã/phường đó
      passParams: true,
      showView: true, // bộ lọc 764 nhận góc giao/nhận và gửi số giao/nhận lên
    },
    {
      id: "cd",
      no: 2,
      label: "Chuyên đề lớn",
      url: "https://superbi-theodoinhiemvu.hanoi.gov.vn/superset/dashboard/nq57-chuyen-de-chi-tiet-1211/",
      passParams: false, // số liệu toàn Thành phố, không lọc theo đơn vị
      hideIfParam: "id_xa_phuong", // mở theo một xã/phường → ẩn tab Chuyên đề lớn
      noExport: true, // ẩn nút "Xuất tổng hợp Excel" khi đang mở tab này
    },
    {
      id: "td",
      no: 3,
      label: "Tình hình triển khai thí điểm",
      url: "https://superbi-theodoinhiemvu.hanoi.gov.vn/superset/dashboard/bcd57-thidiem-trienkhai/",
      passParams: false, // 17 đơn vị thí điểm, bộ lọc Khối/Đơn vị nằm trong dashboard
      hideIfParam: "id_xa_phuong",
      noExport: true,
    },
  ];

  // ============ 2. DỮ LIỆU ============
  // Khung tab không hiển thị số liệu, không đọc queryData

  // ============ 3. HELPER ============
  const esc = (s) =>
    String(s == null ? "" : s).replace(
      /[&<>"]/g,
      (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[c],
    );
  const cssSize = (v) => (v == null || v === "" ? "100%" : isNaN(+v) ? String(v) : v + "px");
  const wrapId = "wrap-" + elementId;
  const paneId = (t) => "pane-" + elementId + "-" + t.id;

  const urlParams = new URLSearchParams(window.location.search);
  // Tab hiển thị: bỏ tab có hideIfParam khi URL mang tham số đó
  const TABS = TAB_CONFIG.filter((t) => !(t.hideIfParam && urlParams.get(t.hideIfParam)));
  function buildUrl(tab) {
    let u = tab.url;
    Object.keys(tab.urlIfParam || {}).forEach((p) => {
      if (urlParams.get(p)) u = tab.urlIfParam[p];
    });
    if (!u) return "";
    if (!/[?&]standalone=/.test(u)) u += (u.indexOf("?") >= 0 ? "&" : "?") + "standalone=3";
    if (tab.passParams) {
      CONFIG.passParams.forEach((p) => {
        const v = urlParams.get(p);
        if (v) u += "&" + p + "=" + encodeURIComponent(v);
      });
    }
    return u;
  }
  const clockText = () => {
    const d = new Date(),
      p = (x) => ("0" + x).slice(-2);
    return (
      p(d.getHours()) +
      ":" +
      p(d.getMinutes()) +
      " · " +
      p(d.getDate()) +
      "/" +
      p(d.getMonth() + 1) +
      "/" +
      d.getFullYear()
    );
  };
  const ICON = {
    clock:
      '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/></svg>',
    xls: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M14 3H6a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V9z"/><path d="M14 3v6h6"/><path d="m9 13 4 5m0-5-4 5"/></svg>',
    full: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M8 3H5a2 2 0 0 0-2 2v3m18 0V5a2 2 0 0 0-2-2h-3m0 18h3a2 2 0 0 0 2-2v-3M3 16v3a2 2 0 0 0 2 2h3"/></svg>',
    empty:
      '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="4" width="18" height="16" rx="2"/><path d="M3 9h18M8 14h8M8 17h5"/></svg>',
  };

  // ============ 4. CSS ============
  const styleEl = `
    <style>
      #${wrapId}{--red:#b4161f;--red-2:#a81620;--line:#dbe4ee;--ink:#132a45;--ink-2:#5a6b84;--ink-3:#8496ad;
        font-family:'Inter',-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Arial,sans-serif;
        display:flex;flex-direction:column;box-sizing:border-box;overflow:hidden;background:#edf1f4;color:var(--ink);}
      #${wrapId} *{box-sizing:border-box;margin:0;padding:0;}
      #${wrapId} button{font-family:inherit;}

      /* Header */
      #${wrapId} .top{height:66px;flex:none;display:flex;align-items:center;gap:16px;padding:0 22px;background:#fff;
        border-bottom:3px solid var(--red);box-shadow:0 1px 4px rgba(16,40,74,.08);}
      #${wrapId} .logo{width:52px;height:52px;border-radius:50%;flex:none;background:#fff;padding:2px;overflow:hidden;
        box-shadow:0 0 0 2px rgba(200,30,40,.18),0 2px 6px rgba(16,40,74,.14);}
      #${wrapId} .logo img{width:100%;height:100%;object-fit:contain;display:block;}
      #${wrapId} .brand h1{color:var(--red);font-size:22px;font-weight:800;letter-spacing:.6px;line-height:1.1;text-align:start;}
      #${wrapId} .brand .sub{color:#000;font-size:12px;font-weight:600;margin-top:3px;}
      #${wrapId} .sp{flex:1;}
      #${wrapId} .pill{display:inline-flex;align-items:center;gap:7px;height:32px;padding:0 12px;border-radius:999px;
        background:#f6f9fb;border:1px solid var(--line);color:var(--ink);font-size:12px;font-weight:800;white-space:nowrap;
        font-variant-numeric:tabular-nums;}
      #${wrapId} .pill svg{width:14px;height:14px;color:var(--ink-2);}

      /* Thanh tab */
      #${wrapId} .nav{height:46px;flex:none;display:flex;align-items:stretch;gap:4px;padding:0 16px 0 0;background:#fff;
        border-bottom:1px solid var(--line);}
      #${wrapId} .tab{position:relative;display:flex;align-items:center;gap:8px;padding:0 18px;border:0;background:transparent;
        color:var(--ink-2);font-size:13.5px;font-weight:700;cursor:pointer;white-space:nowrap;}
      #${wrapId} .tab .no{width:22px;height:22px;border-radius:6px;display:grid;place-items:center;font-size:11.5px;font-weight:800;
        background:#e9eff5;color:var(--ink-2);}
      #${wrapId} .tab:hover{color:var(--red-2);}
      #${wrapId} .tab.on{color:#8c1017;}
      #${wrapId} .tab.on .no{background:var(--red-2);color:#fff;}
      #${wrapId} .tab.on::after{content:"";position:absolute;left:12px;right:12px;bottom:0;height:3px;border-radius:3px 3px 0 0;background:var(--red-2);}
      #${wrapId} .tab .cnt{min-width:22px;height:20px;padding:0 7px;border-radius:999px;display:inline-grid;place-items:center;
        font-size:11px;font-weight:800;background:#fde4e4;color:var(--red);font-variant-numeric:tabular-nums;}
      #${wrapId} .tab.on .cnt{background:var(--red-2);color:#fff;}
      #${wrapId} .act{display:flex;align-items:center;gap:8px;margin-left:auto;}
      #${wrapId} .vseg{display:inline-flex;height:30px;border:1px solid var(--line);border-radius:7px;overflow:hidden;background:#f6f9fb;}
      #${wrapId} .vseg button{border:0;background:transparent;padding:0 14px;font-size:12px;font-weight:800;color:var(--ink-2);
        cursor:pointer;display:flex;align-items:center;gap:7px;white-space:nowrap;}
      #${wrapId} .vseg button + button{border-left:1px solid var(--line);}
      #${wrapId} .vseg button .n{font-size:10.5px;font-weight:800;color:var(--ink-3);background:#eef2f7;border-radius:999px;
        padding:1px 7px;font-variant-numeric:tabular-nums;}
      #${wrapId} .vseg button:hover{color:var(--red-2);}
      #${wrapId} .vseg button.on{background:var(--red-2);color:#fff;}
      #${wrapId} .vseg button.on .n{background:rgba(255,255,255,.24);color:#fff;}
      #${wrapId} .btn{height:30px;padding:0 12px;border-radius:7px;border:1px solid var(--line);background:#f6f9fb;color:var(--ink-2);
        font-size:12px;font-weight:700;cursor:pointer;display:inline-flex;align-items:center;gap:6px;white-space:nowrap;}
      #${wrapId} .btn svg{width:14px;height:14px;}
      #${wrapId} .btn:hover{border-color:var(--red-2);color:var(--red-2);}

      /* Nội dung tab */
      #${wrapId} .body{position:relative;flex:1;min-height:0;}
      #${wrapId} .pane{position:absolute;inset:0;width:100%;height:100%;border:none;background:#f8fafc;
        opacity:0;z-index:-1;pointer-events:none;transition:opacity .3s ease;}
      #${wrapId} .pane.on{opacity:1;z-index:10;pointer-events:auto;}
      #${wrapId} .empty{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:10px;color:var(--ink-3);}
      #${wrapId} .empty svg{width:56px;height:56px;color:#c3ccd8;}
      #${wrapId} .empty b{font-size:15px;color:var(--ink-2);}
      #${wrapId} .empty span{font-size:12.5px;}

      #${wrapId} .toast{position:absolute;right:20px;bottom:20px;z-index:50;background:#2e0b0e;color:#fbeced;border-left:4px solid #f2c230;
        padding:10px 14px;border-radius:8px;font-size:12.5px;font-weight:600;box-shadow:0 12px 30px rgba(0,0,0,.3);
        opacity:0;transform:translateY(8px);transition:all .25s;pointer-events:none;}
      #${wrapId} .toast.on{opacity:1;transform:none;}
    </style>`;

  // ============ 5. RENDER HTML ============
  const startTab = TABS.some((t) => t.id === CONFIG.defaultTab) ? CONFIG.defaultTab : TABS[0].id;
  const vn = (n) => (Number(n) || 0).toLocaleString("vi-VN");
  const counts = Object.assign({}, CONFIG.initCounts);

  const tabsHtml = TABS.map(
    (t, i) => `
    <button class="tab${t.id === startTab ? " on" : ""}" data-tab="${t.id}">
      <span class="no">${i + 1}</span>${esc(t.label)}
    </button>`,
  ).join("");
  const viewHtml = `
    <span class="vseg">
      <button data-view="giao">Nhiệm vụ giao</button>
      <button data-view="nhan">Nhiệm vụ nhận</button>
    </span>`;

  const panesHtml = TABS.map((t) => {
    const url = buildUrl(t),
      on = t.id === startTab;
    if (!url) {
      return `<div class="pane empty${on ? " on" : ""}" id="${paneId(t)}">
        ${ICON.empty}<b>${esc(t.label)}</b><span>Chưa cấu hình link dashboard cho tab này</span></div>`;
    }
    // Lazy load: chỉ tab đang mở có src, tab khác chờ ở data-src
    return `<iframe class="pane${on ? " on" : ""}" id="${paneId(t)}" title="${esc(t.label)}" ${on ? "src" : "data-src"}="${esc(url)}"></iframe>`;
  }).join("");

  function render() {
    rootEl.innerHTML = `
      <div id="${wrapId}" style="width:${cssSize(width)};height:${cssSize(height)};">
        ${styleEl}
        <header class="top">
          <div class="logo"><img src="${CONFIG.logoSrc}" alt="Logo"></div>
          <div class="brand"><h1>${esc(CONFIG.title)}</h1><div class="sub">${esc(CONFIG.subText)}</div></div>
          <div class="sp"></div>
          <span class="pill">${ICON.clock}<span class="clk">${clockText()}</span></span>
        </header>
        <nav class="nav">
          ${tabsHtml}
          <div class="act">
            ${viewHtml}
            ${CONFIG.showExport ? `<button class="btn" data-act="export">${ICON.xls}Xuất tổng hợp Excel</button>` : ""}
          </div>
        </nav>
        <div class="body">${panesHtml}</div>
        <div class="toast"></div>
      </div>`;
  }

  // ============ 6. XỬ LÝ CHUYỂN TAB, XUẤT EXCEL, ĐỒNG HỒ ============
  let wrapEl = null,
    clockTimer = null,
    toastTimer = null,
    curTab = startTab,
    curView = CONFIG.defaultView;

  function toast(msg) {
    const t = wrapEl && wrapEl.querySelector(".toast");
    if (!t) return;
    t.textContent = msg;
    t.classList.add("on");
    clearTimeout(toastTimer);
    toastTimer = setTimeout(() => t.classList.remove("on"), 3000);
  }

  function syncExportBtn() {
    const btn = wrapEl.querySelector('[data-act="export"]');
    const tab = TABS.find((t) => t.id === curTab);
    if (btn) btn.style.display = tab && tab.noExport ? "none" : "";
    const seg = wrapEl.querySelector(".vseg");
    if (seg) seg.style.display = tab && tab.showView ? "" : "none";
  }

  function syncView() {
    wrapEl
      .querySelectorAll("[data-view]")
      .forEach((b) => b.classList.toggle("on", b.getAttribute("data-view") === curView));
  }

  // Gửi góc giao/nhận cho dashboard con của các tab có showView
  function postView() {
    TABS.filter((t) => t.showView).forEach((t) => {
      const pane = wrapEl.querySelector("#" + paneId(t));
      if (pane && pane.tagName === "IFRAME" && pane.contentWindow && pane.getAttribute("src")) {
        pane.contentWindow.postMessage({ type: CONFIG.viewMessage, view: curView }, "*");
      }
    });
  }

  function setView(v) {
    curView = v;
    syncView();
    postView();
  }

  function renderCounts() {
    wrapEl.querySelectorAll("[data-cnt]").forEach((el) => {
      el.textContent = vn(counts[el.getAttribute("data-cnt")]);
    });
  }

  function toggleFull() {
    if (!document.fullscreenElement) {
      const req = wrapEl.requestFullscreen || wrapEl.webkitRequestFullscreen;
      if (req) req.call(wrapEl);
    } else if (document.exitFullscreen) {
      document.exitFullscreen();
    }
  }

  // Dashboard con gửi số thật: {type: countMessage, nv?, giao?, nhan?, cd?}
  const onMessage = (e) => {
    const d = e && e.data;
    if (!d || d.type !== CONFIG.countMessage || !wrapEl) return;
    ["nv", "giao", "nhan", "cd"].forEach((k) => {
      if (d[k] != null) counts[k] = Number(d[k]) || 0;
    });
    renderCounts();
  };

  function switchTab(id) {
    curTab = id;
    syncExportBtn();
    wrapEl.querySelectorAll(".tab").forEach((b) => b.classList.toggle("on", b.getAttribute("data-tab") === id));
    TABS.forEach((t) => {
      const pane = wrapEl.querySelector("#" + paneId(t));
      if (!pane) return;
      const on = t.id === id;
      pane.classList.toggle("on", on);
      const hiddenSrc = on && pane.getAttribute("data-src");
      if (hiddenSrc) {
        pane.setAttribute("src", hiddenSrc);
        pane.removeAttribute("data-src");
      }
    });
  }

  function exportExcel() {
    const tab = TABS.find((t) => t.id === curTab);
    const pane = wrapEl.querySelector("#" + paneId(tab));
    if (!pane || pane.tagName !== "IFRAME" || !pane.contentWindow) {
      toast('Chưa có dashboard cho tab "' + tab.label + '" để xuất Excel');
      return;
    }
    pane.contentWindow.postMessage({ type: CONFIG.exportMessage, tab: tab.id }, "*");
  }

  const onClick = (e) => {
    const tabBtn = e.target.closest("[data-tab]");
    if (tabBtn) {
      switchTab(tabBtn.getAttribute("data-tab"));
      return;
    }
    const viewBtn = e.target.closest("[data-view]");
    if (viewBtn) {
      setView(viewBtn.getAttribute("data-view"));
      return;
    }
    if (e.target.closest('[data-act="export"]')) exportExcel();
    if (e.target.closest('[data-act="full"]')) toggleFull();
  };

  const initTimer = setTimeout(() => {
    render();
    wrapEl = document.getElementById(wrapId);
    if (!wrapEl) return;
    syncExportBtn();
    syncView();
    wrapEl.addEventListener("click", onClick);
    window.addEventListener("message", onMessage);
    // dashboard con tải xong thì nhận góc giao/nhận hiện tại
    wrapEl.querySelectorAll("iframe.pane").forEach((f) => f.addEventListener("load", postView));
    clockTimer = setInterval(() => {
      const c = wrapEl.querySelector(".clk");
      if (c) c.textContent = clockText();
    }, 30000);
  }, 0);

  // ============ 7. CLEANUP ============
  rootEl.__bcdTabCleanup = function () {
    clearTimeout(initTimer);
    clearTimeout(toastTimer);
    clearInterval(clockTimer);
    window.removeEventListener("message", onMessage);
    if (wrapEl) wrapEl.removeEventListener("click", onClick);
  };

  return {};
};
